using Entries=std::map<std::string,std::string>;
constexpr const char* ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
constexpr const char* relns="http://schemas.openxmlformats.org/officeDocument/2006/relationships";
constexpr const char* ownerns="urn:tigersheets:pivot:v1";
std::string local(const char* name){const std::string value(name);const auto pos=value.find(':');return pos==std::string::npos?value:value.substr(pos+1);}
pugi::xml_node child(pugi::xml_node parent,const char* name){for(auto node:parent.children())if(local(node.name())==name)return node;return {};}
std::string qualified(pugi::xml_node parent,const char* name){const std::string root=parent.name();const auto colon=root.find(':');return colon==std::string::npos?std::string(name):root.substr(0,colon+1)+name;}
std::string attr(pugi::xml_node node,const char* name){for(auto a:node.attributes())if(local(a.name())==name)return a.value();return {};}
void parse(pugi::xml_document& doc,const std::string& bytes){if(!doc.load_buffer(bytes.data(),bytes.size()))throw std::runtime_error("Invalid native pivot XML");}
std::string xml(const pugi::xml_document& doc){std::ostringstream stream;doc.save(stream,"",pugi::format_raw,pugi::encoding_utf8);auto text=stream.str();std::string output;output.reserve(text.size());for(char c:text)if(c=='\r')output+="&#13;";else output+=c;return output;}
std::string column(int c){std::string s;while(c>0){--c;s.insert(s.begin(),static_cast<char>('A'+c%26));c/=26;}return s;}
std::string range(const Json& r){return column(r.at("col1"))+std::to_string(r.at("row1").get<int>())+":"+column(r.at("col2"))+std::to_string(r.at("row2").get<int>());}
const Json& sheet(const Json& book,const std::string& id){for(const auto& s:book.at("sheets"))if(s.at("id")==id)return s;throw std::runtime_error("Native pivot worksheet is missing");}
std::string relpart(const std::string& part){const std::filesystem::path p(part);return (p.parent_path()/"_rels"/(p.filename().string()+".rels")).generic_string();}
std::string target(const std::string& base,const std::string& value){auto path=value.starts_with('/')?std::filesystem::path(value.substr(1)):std::filesystem::path(base).parent_path()/value;auto normalized=path.lexically_normal().generic_string();if(normalized.starts_with("../")||normalized.starts_with('/'))throw std::runtime_error("Unsafe native pivot relationship");return normalized;}
void relationships(pugi::xml_document& doc,const Entries& entries,const std::string& part){if(entries.contains(part))parse(doc,entries.at(part));else doc.append_child("Relationships").append_attribute("xmlns")="http://schemas.openxmlformats.org/package/2006/relationships";}
std::string relationship(pugi::xml_node root,const std::string& base,const std::string& part,const std::string& type){std::string id="tigerPivot";bool used;do{used=false;for(auto n:root.children())if(id==n.attribute("Id").value()){used=true;id+='x';break;}}while(used);auto n=root.append_child(qualified(root,"Relationship").c_str());n.append_attribute("Id")=id.c_str();n.append_attribute("Type")=(std::string(relns)+"/"+type).c_str();n.append_attribute("Target")=std::filesystem::path(part).lexically_relative(std::filesystem::path(base).parent_path()).generic_string().c_str();return id;}
void contentType(pugi::xml_node root,const std::string& part,const char* type){for(auto n:root.children())if("/"+part==n.attribute("PartName").value())return;auto n=root.append_child(qualified(root,"Override").c_str());n.append_attribute("PartName")=("/"+part).c_str();n.append_attribute("ContentType")=type;}
std::string uniquePart(const Entries& entries,const std::string& prefix){int n=1;while(entries.contains(prefix+std::to_string(n)+".xml"))++n;return prefix+std::to_string(n)+".xml";}

std::string calendarDate(double serial){using namespace std::chrono;if(!std::isfinite(serial)||serial<1||serial>=2958466||std::floor(serial)==60)throw std::runtime_error("Native date grouping requires real 1900-system calendar dates; serial day 60 is unsupported");const auto whole=static_cast<long long>(std::floor(serial));const auto day=sys_days{year{1899}/12/31}+days{whole-(whole>60?1:0)};const year_month_day calendar{day};auto nanos=static_cast<long long>(std::llround((serial-whole)*86400.0L*1000000000.0L));const auto hours=nanos/3600000000000LL;nanos%=3600000000000LL;const auto minutes=nanos/60000000000LL;nanos%=60000000000LL;const auto seconds=nanos/1000000000LL;nanos%=1000000000LL;std::ostringstream out;out<<std::setfill('0')<<std::setw(4)<<static_cast<int>(calendar.year())<<'-'<<std::setw(2)<<static_cast<unsigned>(calendar.month())<<'-'<<std::setw(2)<<static_cast<unsigned>(calendar.day())<<'T'<<std::setw(2)<<hours<<':'<<std::setw(2)<<minutes<<':'<<std::setw(2)<<seconds;if(nanos){std::ostringstream fraction;fraction<<std::setfill('0')<<std::setw(9)<<nanos;auto text=fraction.str();while(text.back()=='0')text.pop_back();out<<'.'<<text;}return out.str();}
