int formatId(Entries& entries,const std::string& format){if(format.empty()||format=="General")return 0;std::string part="xl/styles.xml";if(entries.contains("xl/_rels/workbook.xml.rels")){pugi::xml_document rels;parse(rels,entries.at("xl/_rels/workbook.xml.rels"));for(auto relation:rels.document_element().children())if(std::string(relation.attribute("Type").value()).ends_with("/styles"))part=target("xl/workbook.xml",relation.attribute("Target").value());}pugi::xml_document doc;if(entries.contains(part))parse(doc,entries.at(part));else parse(doc,R"(<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="1"><font/></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="1"><xf/></cellXfs></styleSheet>)");auto formats=child(doc.document_element(),"numFmts");if(!formats)formats=doc.document_element().prepend_child(qualified(doc.document_element(),"numFmts").c_str());int next=164;for(auto n:formats.children()){if(format==n.attribute("formatCode").value())return n.attribute("numFmtId").as_int();next=std::max(next,n.attribute("numFmtId").as_int()+1);}auto n=formats.append_child(qualified(formats,"numFmt").c_str());n.append_attribute("numFmtId")=next;n.append_attribute("formatCode")=format.c_str();auto count=formats.attribute("count");if(!count)count=formats.append_attribute("count");count=static_cast<unsigned>(std::distance(formats.begin(),formats.end()));entries[part]=xml(doc);return next;}

