pugi::xml_node marker(pugi::xml_node root){auto ext=child(root,"extLst");for(auto e:ext.children())for(auto n:e.children())if(local(n.name())=="pivot"&&std::string(n.attribute("xmlns:ts").value())==ownerns)return n;return {};}
