bool ownedNativePivotPart(const std::string& bytes){try{pugi::xml_document doc;parse(doc,bytes);return static_cast<bool>(marker(doc.document_element()));}catch(...){return false;}}
std::set<std::string> ownedNativePivotParts(const WorkbookPackage& source){
 std::set<std::string> result,ids;for(const auto& pivot:source.baseline.value("pivots",Json::array()))if(pivot.value("version",0)==1){ids.insert(pivot.at("id").get<std::string>());if(pivot.contains("native"))for(const auto* key:{"tablePart","cachePart","recordsPart"})if(pivot["native"].contains(key)){const auto part=pivot["native"][key].get<std::string>();result.insert(part);if(key!=std::string("recordsPart"))result.insert(relpart(part));}}
 for(const auto& [part,bytes]:source.entries)if(part.starts_with("xl/pivotTables/")&&part.ends_with(".xml")){
  pugi::xml_document table;parse(table,bytes);if(!ids.contains(marker(table.document_element()).attribute("id").value()))continue;result.insert(part);const auto tableRels=relpart(part);result.insert(tableRels);if(!source.entries.contains(tableRels))continue;pugi::xml_document relations;parse(relations,source.entries.at(tableRels));for(auto relation:relations.document_element().children())if(std::string(relation.attribute("Type").value()).ends_with("/pivotCacheDefinition")){const auto cache=target(part,relation.attribute("Target").value());result.insert(cache);const auto cacheRels=relpart(cache);result.insert(cacheRels);if(!source.entries.contains(cacheRels))continue;pugi::xml_document records;parse(records,source.entries.at(cacheRels));for(auto r:records.document_element().children())if(std::string(r.attribute("Type").value()).ends_with("/pivotCacheRecords"))result.insert(target(cache,r.attribute("Target").value()));}
 }return result;
}
