 for(auto n=types.document_element().first_child();n;){auto next=n.next_sibling();const std::string name=n.attribute("PartName").value();if(name.starts_with('/')&&removed.contains(name.substr(1)))types.document_element().remove_child(n);n=next;}for(const auto& part:removed)entries.erase(part);entries["xl/workbook.xml"]=xml(workbook);entries["[Content_Types].xml"]=xml(types);
